       System.Resources.ResourceManager rm = new System.Resources.ResourceManager("Resources.Strings",
                        System.Reflection.Assembly.Load("App_GlobalResources"));
       private static string[] onesMapping =
              new string[] {
           "zero", "një", "dy", "tre", "katër", "pesë", "gjashtë", "shtatë", "tetë", "nëntë",
           "dhjetë", "njëmbëdhjetë", "dymbëdhjetë", "trembëdhjetë", "katërmbëdhjetë", "pesëmbëdhjetë",
           "gjashtëmbedhjetë", "shtatëmbëdhjetë", "tetëmbëdhjetë", "nëntëmbëdhjetë"};


private static string[] tensMapping =
new string[] { "njëzet", "tridhjetë", "dyzet", "pesëdhjetë", "gjashtëdhjetë", "shtatëdhjetë", "tetëdhjetë", "nëntëdhjetë"
       };
       private static string[] groupMapping =
           new string[] {
           "qind", "mijë", "milion", "miliard", "trilion"
       };
       public String changeToWords(String numb)
       {
           String val = "", wholeNo = numb, points = "", andStr = "", pointStr = "";
           String endStr = ("");
           if (numb.Trim() == "")
               return "";
           try
           {
               int decimalPlace = numb.IndexOf(".");
               int idxPresjes = numb.IndexOf(",");
               if (decimalPlace > 0 && idxPresjes <= 0)
               {
                   wholeNo = numb.Substring(0, decimalPlace);
                   points = numb.Substring(decimalPlace + 1);
                   if (Convert.ToInt32(points) > 0)
                   {
                       andStr = ("dhe");
                       pointStr = (" ") + EnglishFromNumber(int.Parse(points)) + (" qindarka");
                   }
               }
               else if (idxPresjes > 0 && decimalPlace <= 0)
               {
                   string[] pjeset = numb.Split(',');
                   string numri = "";
                   for (int i = 0; i < pjeset.Length; i++)
                       numri += pjeset[i];
                   wholeNo = numri;
               }
               else if (idxPresjes > 0 && decimalPlace > 0)
               {
                   string[] pjeset = numb.Split(',');
                   string numri = "";
                   for (int i = 0; i < pjeset.Length; i++)
                       numri += pjeset[i];
                   numb = numri;
                   decimalPlace = numb.IndexOf(".");
                   wholeNo = numb.Substring(0, decimalPlace);
                   points = numb.Substring(decimalPlace + 1);
                   if (Convert.ToInt32(points) > 0)
                   {
                       andStr = ("dhe");
                       pointStr = (" ") + EnglishFromNumber(int.Parse(points)) + (" qindarka");
                   }
               }
               val = String.Format("{0} {1}{2} {3}", EnglishFromNumber(int.Parse(wholeNo)).Trim(), andStr, pointStr, endStr);
           }
           catch {; }

           string fundi = val.Substring(val.Length - 4, 3);
           if (fundi == " e ")
               val = val.Substring(0, val.Length - 4);

           return val;
       }

       public static string EnglishFromNumber(long number)
       {
           if (number == 0)
           {
               return onesMapping[number];
           }

           string retVal = null;
           int group = 0;
           while (number > 0)
           {
               int numberToProcess = (int)(number % 1000);
               number = number / 1000;

               string groupDescription = ProcessGroup(numberToProcess);
               if (groupDescription != null)
               {
                   if (group > 0)
                   {
                       retVal = groupMapping[group] + " e " + retVal;
                   }
                   retVal = groupDescription + " " + retVal;
               }

               group++;
           }

           return /*sign + */" " + retVal;
       }

       private static string ProcessGroup(int number)
       {
           int tens = number % 100;
           int hundreds = number / 100;

           string retVal = null;
           if (hundreds > 0)
           {
               retVal = onesMapping[hundreds] + " " + groupMapping[0];
           }
           if (tens > 0)
           {
               if (tens < 20)
               {
                   retVal += ((retVal != null) ? " e " : "") + onesMapping[tens];
               }
               else
               {
                   int ones = tens % 10;
                   tens = (tens / 10) - 2; // 20's offset

                   retVal += ((retVal != null) ? "  e " : "") + tensMapping[tens];

                   if (ones > 0)
                   {
                       retVal += ((retVal != null) ? " e " : "") + onesMapping[ones];
                   }
               }
           }

           return retVal;
       }


private void xrLabel24_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
       {
            string emri = Convert.ToString(GetCurrentColumnValue("EMER"));
            string mbiemri = Convert.ToString(GetCurrentColumnValue("MBIEMER"));
            string pozicioni =Convert.ToString(GetCurrentColumnValue("Pozicioni"));
            string paga = string.Empty;
            string pagaNeFjale = string.Empty;
            string pagaNeto = string.Empty;
            string pagaNetoFjale = string.Empty;


           if (GetCurrentColumnValue("PAGA") != null)
           {
               paga = String.Format("{0:#,#.00}", GetCurrentColumnValue("PAGA"));
               if (paga !=null)
                   pagaNeFjale = changeToWords(paga);
           }

           if (GetCurrentColumnValue("PagaNeto") != null)
           {
               pagaNeto = String.Format("{0:#,#.00}", GetCurrentColumnValue("PagaNeto"));
               if (pagaNeto != null)
                   pagaNetoFjale = changeToWords(pagaNeto);
           }

           xrLabel24.Text = "Vërtetojmë se Z/Zj " + emri +" "+ mbiemri + ", është punonjës i Qendrës Kombëtare të Biznesit në pozicionin " +
               pozicioni + " me pagën mujore prej " + paga + " bruto (" + pagaNeFjale +  ") lekë dhe pagë mujore neto " + pagaNeto + " (" + pagaNetoFjale + ") lekë.";

       }




